import {footballDetails as data} from './football-data.js';
export function createFootballFeature({text,escape,L,icon}){
 const links=references=>references.map(s=>`<a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.name)}</a>`).join('');
 const photograph=p=>`<figure class="stadium-photo"><img src="${escape(p.src)}" alt="${escape(text(p.caption))}" width="${p.width}" height="${p.height}" loading="lazy" decoding="async"><figcaption>${escape(text(p.caption))}<small>${escape(p.author)} · ${p.width} × ${p.height} px</small><a href="${escape(p.source)}" target="_blank" rel="noopener noreferrer">${L('Source · © club','المصدر · © النادي','Source · © club','Fuente · © club')}</a></figcaption></figure>`;
 function section(){return `<section class="football-leadership"><div class="section-heading"><div><div class="eyebrow">${L('Le MAT aujourd’hui','الماط اليوم','MAT today','El MAT hoy')}</div><h2>${L('Les visages du club.','وجوه النادي.','The people behind the club.','Las personas del club.')}</h2><p>${L('Vérification éditoriale : 10 octobre 2026. Les dernières confirmations du club sont indiquées pour chaque fonction.','مراجعة تحريرية: 10 أكتوبر 2026. آخر تأكيد رسمي من النادي موضح لكل منصب.','Editorial check: 10 October 2026. The club’s latest confirmation is shown for each role.','Revisión editorial: 10 de octubre de 2026. Se indica la última confirmación oficial del club para cada cargo.')}</p></div></div><div class="leadership-layout"><div class="leadership-cards">${data.leadership.map(p=>`<article><div class="eyebrow">${p.role==='coach'?L('Entraîneur','المدرب','Head coach','Entrenador'):L('Président','الرئيس','President','Presidente')}</div><h3>${escape(document.documentElement.lang==='ar'?p.nameArabic:p.name)}</h3><p>${escape(text(p.description))}</p><small>${L('Confirmation officielle','تأكيد رسمي','Official confirmation','Confirmación oficial')} · <time datetime="${p.confirmedOn}">${p.confirmedOn}</time></small><a class="text-button" href="${escape(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${L('Lire le communiqué','اقرأ البلاغ','Read the announcement','Leer el comunicado')}${icon('chevron')}</a></article>`).join('')}</div>${photograph(data.leadershipPhoto)}</div></section><section class="stadium-section"><div class="section-heading"><div><div class="eyebrow">${L('Le terrain & la mémoire','الملعب والذاكرة','The ground & its memory','El campo y su memoria')}</div><h2>${escape(text(data.stadium.name))}</h2><p>${escape(text(data.stadium.intro))}</p></div></div><div class="stadium-gallery">${data.stadium.photos.map(photograph).join('')}</div><div class="stadium-history"><h3>${L('Un terrain, plusieurs époques','ملعب عبر العصور','One ground through the years','Un campo a través del tiempo')}</h3><p>${escape(text(data.stadium.history))}</p><div class="detail-source">${links(data.stadium.sources)}</div><p class="source-caption">${escape(text(data.stadium.visit))}</p></div></section>`;}
 return {section,crest:data.crest};
}
